    $ch1Title = "वीरवती का व्रत-संकल्प";
    $ch1Story = "प्राचीन काल की बात है। पृथ्वी पर एक प्रतापी एवं धर्मात्मा राजा राज्य करते थे। उनकी रानी परम सती, शीलवती और शिव-गौरी की अनन्य भक्त थी। राजा-रानी की एकमात्र कन्या थी — वीरवती। वह रूप में अप्सरा-सी, गुणों में सरस्वती-सी और सेवा में लक्ष्मी-सी थी। घर में बड़ों की आज्ञा मानने वाली, गौरी-शंकर की पूजा में तत्पर और स्त्रियों के धर्म को जानने वाली वीरवती राजा-रानी के नेत्रों की पुतली थी।\n\nसमय आया और राजा ने योग्य वर देखकर वीरवती का विवाह एक धर्मात्मा राजकुमार से कर दिया। विवाह के बाद वीरवती ससुराल में सुखपूर्वक रहने लगी। कुछ समय पश्चात वह अपने मायके आई। माता ने कन्या को देखा तो हृदय आनन्द से भर गया। उसने वीरवती को अपने पास बिठाया और कहा —\n\n“पुत्रि! तुम ससुराल में सुख से रहो। अब मैं तुम्हें स्त्रियों के एक परम पुण्य व्रत का महात्म्य बताती हूँ। कार्तिक कृष्ण चतुर्थी को सुहागिन स्त्रियाँ करवा चौथ का व्रत रखती हैं। इस दिन माँ गौरी, भगवान शिव और चन्द्रमा का पूजन किया जाता है। जो स्त्री इस व्रत को श्रद्धा से करती है, उसके सौभाग्य की रक्षा होती है और पति-पत्नी में अटूट प्रेम रहता है।”\n\nवीरवती ने माता के मुख से व्रत का महात्म्य सुना तो उसका हृदय श्रद्धा से भर गया। उसने हाथ जोड़कर कहा —\n\n“माता! मैं यह व्रत अवश्य करूँगी। मेरे पति की आयु, हमारे सुहाग और परिवार की रक्षा के लिए मैं माँ गौरी की कृपा चाहती हूँ।”\n\nरानी ने कहा —\n\n“पुत्रि, यह व्रत निर्जला रखा जाता है। दिनभर अन्न-जल ग्रहण नहीं करना होता है। सायं चन्द्रोदय होने पर चन्द्रमा और गौरी-शिव का पूजन कर पारण किया जाता है। व्रत में श्रद्धा और संकल्प सबसे बड़ा है।”\n\nवीरवती ने व्रत का संकल्प ले लिया। चतुर्थी का दिन आया। उसने ब्रह्ममुहूर्त में स्नान किया, सुहाग के वस्त्र पहने, माँ गौरी और भगवान शिव का ध्यान किया। कलश के समीप बैठकर उसने जल एवं अक्षत हाथ में लेकर संकल्प किया —\n\n“ॐ गौर्यै नमः, शिवाय नमः, सोमाय नमः। मैं अपने पति के दीर्घायुष्य, सौभाग्य और परिवार की शान्ति के लिए यह निर्जला व्रत रखती हूँ। माँ गौरी, मेरी मनोकामना पूर्ण करें।”\n\nवीरवती ने गौरी-शिव का विधिवत पूजन किया और करवा चौथ की कथा श्रद्धापूर्वक सुनी। दिन बीतने लगा। सूर्य देव अपने तेज से तप रहे थे और वीरवती के प्राणी को भूख-प्यास सताने लगी। परन्तु वह प्रतिज्ञा पर दृढ़ रही। वह समय-समय पर गौरी माँ को स्मरण करती और संकल्प का पाठ करती —\n\n“गौरीं शिवां भवानीं भजे, पतिव्रतानां सुहागं देहि मे जगदम्बिके।\nअर्थात् — हे जगदम्बिके! मैं गौरी एवं शिव की शरण हूँ; पतिव्रताओं को सुहाग प्रदान करने वाली माँ, मुझे सौभाग्य दो।”\n\nवीरवती के सात भाई थे। उन्हें अपनी बहन पर अत्यन्त स्नेह था। जब उन्होंने देखा कि बहन दिनभर बिना अन्न-जल के व्रत कर रही है और उसका मुख कुम्हलाने लगा है, तो उनका हृदय व्याकुल हो उठा। वे उसके पास आकर बोले —\n\n“बहन! तुम निराहार क्यों बैठी हो? थोड़ा जल या फल ग्रहण कर लो। तुम्हारा शरीर कमजोर पड़ जाएगा।”\n\nवीरवती ने हाथ जोड़कर कहा —\n\n“भाई! यह मेरा व्रत है। मैं चन्द्रोदय से पहले कुछ ग्रहण नहीं करूँगी। यह व्रत मेरे पति के सौभाग्य और हमारे सुहाग के लिए है। माँ गौरी मेरी रक्षा करेंगी।”\n\nभाइयों ने बहुत समझाया, पर वीरवती अपने संकल्प पर अडिग रही। सूर्यास्त होने में अभी समय था और चन्द्रमा के उदय होने की प्रतीक्षा थी। भाई बहन के प्रेम से व्याकुल होकर आपस में कहने लगे —\n\n“बहन भूख-प्यास से व्याकुल है। यदि चन्द्रमा देर से उगेगा तो कहीं वह और कमजोर न पड़ जाए। हमें कोई ऐसा उपाय करना चाहिए कि उसे चन्द्रमा का दर्शन हो जाए।”\n\nइस प्रकार वीरवती के भाई अपने स्नेह के कारण उसे व्रत पूर्ण करने का भ्रम देने की सोचने लगे। उधर वीरवती माँ गौरी का ध्यान करती हुई चन्द्रोदय की प्रतीक्षा कर रही थी। उसका हृदय पवित्र था, संकल्प दृढ़ था, परन्तु भाइयों का अति-स्नेह उसके व्रत की परीक्षा बनने वाला था।";

    $ch2Title = "भाइयों की परीक्षा और सुहाग का हरण";
    $ch2Story = "सन्ध्या का समय निकट आ रहा था। आकाश में सूर्यदेव अपनी लालिमा बिखेर रहे थे और पक्षी अपने-अपने नीड़ों की ओर लौट रहे थे। वीरवती पूजा-स्थल पर बैठी थी। उसके सम्मुख मिट्टी का करवा रखा था, जिस पर रोली से स्वस्तिक बना था और जल से भरा हुआ वह करवा ऐसा लग रहा था मानो स्वयं माँ गौरी उसके घर पधारी हों। दीपक की लौ धीरे-धीरे काँप रही थी और वीरवती के अधरों पर गौरी-गीत गूँज रहे थे।\n\nवह बार-बार आकाश की ओर देखती और मन में कहती —\n\n“हे चन्द्रदेव! आप शीघ्र पधारिए। माँ गौरी के आशीर्वाद से मेरा व्रत पूर्ण हो। मेरे पति की आयु की रक्षा हो, हमारा सुहाग अखण्ड रहे।”\n\nपरन्तु उस दिन चन्द्रमा देर से उदय होने वाले थे। सूर्यास्त हो चुका था, पर आकाश में चन्द्रमा का अभी कोई चिह्न नहीं था। वीरवती की भूख-प्यास बढ़ती जा रही थी, पर उसका संकल्प और भी दृढ़ होता जा रहा था।\n\nउधर वीरवती के सातों भाई छत पर खड़े होकर आकाश की ओर देख रहे थे। वे अपनी बहन की दशा देखकर व्याकुल हो उठे। उन्होंने आपस में विचार किया —\n\n“हमारी बहन दिनभर निराहार है। उसका मुख सूख रहा है। चन्द्रमा अभी देर से उगेगा। यदि वह इतनी देर तक भूख-प्यास सहन न कर सकी तो कहीं वह मूर्च्छित न हो जाए। हमें कोई उपाय करना चाहिए जिससे उसे शीघ्र चन्द्रमा का दर्शन हो जाए और वह अपना पारण कर सके।”\n\nभाइयों में सबसे बड़े भाई ने कहा —\n\n“सुनो भाइयों! पीपल के वृक्ष की ओट में एक बड़ा दीपक जलाओ और उसके प्रकाश को इस प्रकार छिपाओ कि छत से देखने पर वह चन्द्रमा के समान प्रतीत हो। फिर छलनी लेकर बहन को दिखाओ। वह समझेगी कि चन्द्रमा उदय हो गया है और वह व्रत पूर्ण कर लेगी।”\n\nभाइयों ने स्नेहवश यह बात स्वीकार कर ली। उन्होंने पीपल की ओट में घी का दीपक जलाया और उसके चारों ओर छलनी रख दी। दूर से देखने पर उस दीपक का प्रकाश चन्द्रमा के समान भासित होने लगा।\n\nफिर सभी भाई बहन के पास आए और अत्यन्त प्रेम से बोले —\n\n“बहन! उठो, देखो तो! चन्द्रमा उदय हो गया है। तुमने अब तक व्रत किया है, अब चन्द्र-दर्शन करके अपना व्रत पूर्ण करो। इतनी देर में तुम निर्बल हो जाओगी।”\n\nवीरवती ने विश्वासपूर्वक आकाश की ओर देखा। उसे चन्द्रमा का प्रकाश दिखाई दिया। उसने हाथ जोड़कर प्रार्थना की —\n\n“ॐ शशधराय नमः। हे चन्द्रदेव! आप अमृतमय हैं, आपके दर्शन से सुहाग की रक्षा होती है। मैं आपका दर्शन करती हूँ, मेरे पति की आयु की रक्षा करें।”\n\nफिर उसने छलनी से छानकर उस प्रकाश की ओर देखा और सोचा कि चन्द्रमा उदय हो चुका है। भाइयों ने उसे जल एवं मिष्ठान दिया और वीरवती ने अपना पारण कर लिया।\n\nपरन्तु जैसे ही वीरवती ने पारण किया, भाइयों का हृदय काँप उठा। क्योंकि उसी क्षण दूर से एक दूत आया और उसने दौड़कर कहा —\n\n“महारानी! आपके पति आज भोजन करते समय अचानक मूर्च्छित होकर गिर पड़े हैं। उनके प्राण नहीं लौट रहे। वैद्य आए हैं, पर वे निरुपाय हैं। आपको शीघ्र बुलाया जा रहा है।”\n\nवीरवती की आँखों के आगे अंधेरा छा गया। वह हाथ जोड़कर भाइयों की ओर देखने लगी और उसका हृदय जान गया कि जो प्रकाश उसने देखा, वह चन्द्रमा नहीं था। यह उसके ही भाइयों का मोह था, जिसने उसे व्रत पूर्ण होने से पहले पारण करा दिया।\n\nवह दौड़कर महल पहुँची। उसके पति का शरीर शान्त पड़ा था। मुख कुम्हलाया हुआ था और आँखें बंद थीं। वीरवती ने उनका मुखमंडल देखा और रो पड़ी —\n\n“हे माँ गौरी! क्या मेरे व्रत में कहीं भूल तो नहीं हुई? क्या मेरी श्रद्धा में कोई अवगुण रह गया, जिससे यह कष्ट मिला? मैंने तो निराहार व्रत किया, पूजन किया, संकल्प लिया। फिर यह विपत्ति क्यों आई?”\n\nवह अपने पति के चरणों में गिर पड़ी और फूट-फूटकर रोने लगी। उसके आँसुओं से पति के चरण पवित्र हो गए। परन्तु उसका हृदय एक क्षण के लिए भी विचलित नहीं हुआ। उसने मन में कहा —\n\n“माँ गौरी! आपने मुझे यह व्रत बताया है। मैं यह व्रत अपने पति के लिए करूँगी। मैं आपकी शरण हूँ। जो हुआ, वह भी आपकी इच्छा से हुआ। पर मैं अपने पति को इस प्रकार नहीं छोड़ सकती।”\n\nवीरवती ने अपने पति के शरीर को अपनी गोद में लिया और रातभर जागरण करती हुई माँ गौरी का ध्यान करने लगी। वह गीत गाती —\n\n“गौरी माँ, शंकर प्रिये, भवानी!\nअबला की रखवाली करो, जगदम्बिके, शुभदायिनी।”\n\nपरन्तु भाइयों ने अपने स्नेह-मोह में जो किया, उससे उनका हृदय भी पश्चाताप से भर गया। वे हाथ जोड़कर बहन के पास बैठे और बोले —\n\n“बहन! हमने जो किया, वह अज्ञानवश किया। हमें तुम्हारे व्रत की पूर्ण विधि का ज्ञान नहीं था। हमने तुम्हें प्रसन्न करने के लिए दीपक का प्रकाश चन्द्रमा समझ लिया। हमें क्षमा कर दो। अब कोई ऐसा उपाय बताओ जिससे हमारे प्राणों के समान जीवनदायी पुण्य उदय हो। हम भी तुम्हारे साथ माँ गौरी की शरण में जाएँगे।”\n\nवीरवती ने अपने भाइयों को देखा। उसके नेत्रों में करुणा थी। उसने कहा —\n\n“भाइयों! अब पश्चाताप की बात नहीं। मैं माँ गौरी की शरण में हूँ। यदि उन्होंने मुझे अपनी पुत्री माना है तो मेरा संकल्प पूर्ण होगा। पर यह विपत्ति उसी अधूरे व्रत का फल है। अब मैं सच्चे हृदय से और विधिपूर्वक व्रत करूँगी। तुम लोग घर जाओ और मेरे पति के लिए प्रार्थना करो। मुझे गौरी-पूजन में एक भी क्षण विचलित मत करो।”\n\nवीरवती ने फिर पूजा-स्थल सजाया। इस बार उसके हृदय में अहंकार नहीं, केवल श्रद्धा थी। उसने माँ गौरी और भगवान शिव की प्रतिमा को जल से स्नान कराया और कहा —\n\n“माता! मेरे पति के प्राण अब आपके हाथ में हैं। मैं अब किसी भी दशा में आपका आशीर्वाद पाने की प्रतीक्षा करूँगी। यहीं बैठी रहूँगी, जब तक आप अपनी कृपा नहीं दिखाएँगी।”\n\nइस प्रकार वह दिन-रात माँ गौरी की उपासना में लग गई। उसका शरीर क्षीण होने लगा, परन्तु उसका संकल्प और भी दृढ़ हो गया। उसकी दिन-रात की आराधना से घर का वातावरण ही पवित्र हो उठा। सारे नगरवासी उसके लिए प्रार्थना करने लगे —\n\n“हे देवी! आप सबके संकट हरने वाली माँ हैं। इस सती का सुहाग लौटाइए।”\n\nवीरवती ने संकल्प लिया कि जब तक माँ गौरी प्रसन्न होकर उसके पति को जीवनदान नहीं देंगी, वह अन्न-जल ग्रहण नहीं करेगी और न ही अपने पति के शरीर का त्याग करेगी। वह अपने पति के चरणों में बैठी, गौरी-गीत गाती और बार-बार यही प्रार्थना करती —\n\n“ॐ गौरि शिवे शान्ते सर्वदेवनमस्कृते।\nसौभाग्यं देहि मे मातः प्रसीद भगवति प्रिये॥”\n\n(हे गौरी! हे शिवे! हे शान्ते! सभी देवताओं द्वारा वन्दिते! हे माता! मुझे सौभाग्य प्रदान करो। हे भगवति! मुझ पर प्रसन्न हो।)\n\nउसकी आराधना से गौरी माता आनन्दित हुईं और भगवान शिव ने माँ पार्वती से कहा —\n\n“देवि! इस सती के हृदय में अपूर्व श्रद्धा है। इसके भाइयों ने मोहवश भूल की, पर इसने अपने संकल्प को नहीं छोड़ा। इसकी भक्ति से मैं प्रसन्न हूँ। अब इसके पति को जीवनदान देने का समय आ गया है।”";

    $ch3Title = "माँ गौरी की कृपा और सुहाग की पुनः प्राप्ति";
    $ch3Story = "कैलाश पर्वत पर भगवान शंकर अपनी परम प्रिय पार्वती के साथ विराजमान थे। माँ गौरी ने अपने स्वामी की ओर देखा और करुणा से भरकर कहा —\n\n“स्वामी! पृथ्वी पर एक सती अपने पति के शोक में दिन-रात बैठी है। उसका नाम वीरवती है। उसने अपने भाइयों के मोहवश अधूरे व्रत का पारण कर लिया था, परन्तु उसका संकल्प सच्चा था। अब वह मेरी शरण में है। मैं उसकी करुण पुकार सुन रही हूँ।”\n\nभगवान शिव ने मुस्कुराकर कहा —\n\n“देवि! तुम्हारी भक्त वीरवती ने मुझे भी प्रसन्न कर लिया है। उसके हृदय में जो श्रद्धा है, वह दुर्लभ है। जो स्त्री अपने सौभाग्य की रक्षा के लिए मेरी अर्धांगिनी की उपासना करती है, उस पर तुम्हारी विशेष कृपा रहती है। अब तुम स्वयं उसके सम्मुख प्रकट होकर उसका संकल्प पूर्ण करो।”\n\nमाँ गौरी ने अपने स्वामी को प्रणाम किया और अपनी माया से उस पृथ्वी-लोक के उस महल में पधारीं, जहाँ वीरवती अपने पति के निर्जीव शरीर के पास बैठी थी। रात का अन्तिम प्रहर था। दीपक की लौ मन्द थी और वीरवती की आँखों से आँसू बह रहे थे। वह गौरी-गीत गाते-गाते मूर्च्छित-सी हो गई थी।\n\nतभी एक दिव्य प्रकाश फैल गया। वीरवती ने आँखें खोलीं तो देखा — साक्षात माँ गौरी उसके सम्मुख खड़ी हैं। उनका मुख कमल के समान प्रकाशमान था, चारों ओर से दिव्य सुगन्ध आ रही थी और उनके चरणों में कमल-पुष्प खिले हुए थे।\n\nवीरवती हाथ जोड़कर वहीं गिर पड़ी —\n\n“माता! माँ! आपने मुझे दर्शन दिए। मैं आपकी पुत्री हूँ। मेरे पति का जीवन लौटाइए। मेरा सुहाग लौटाइए। मैं आपके सिवा किसी को नहीं जानती।”\n\nमाँ गौरी ने करुणापूर्वक उसका सिर सहलाया और कहा —\n\n“पुत्रि! उठो! मैंने तुम्हारा व्रत, तुम्हारी श्रद्धा और तुम्हारा संकल्प स्वीकार किया। तुमने जिस निर्भयता से अपने सौभाग्य की रक्षा के लिए हमारी शरण ली है, उससे मैं प्रसन्न हूँ।”\n\nवीरवती ने रोते हुए कहा —\n\n“माता! मैंने निर्जला व्रत किया था, पूजन किया था, पर मेरे भाइयों की भूल से मेरा पारण सूर्यास्त से पहले हो गया। मेरे इस अपराध को क्षमा कर दीजिए। मैंने अज्ञानवश यह भूल की।”\n\nमाँ गौरी ने कहा —\n\n“पुत्रि! तुम्हारा अपराध तुम्हारा नहीं था। भाइयों की ममता ने तुम्हारे व्रत में विघ्न डाला। परन्तु तुमने उस विपत्ति में भी मेरा स्मरण नहीं छोड़ा। तुमने दिन-रात मेरी आराधना की। मेरे सम्मुख तुम्हारी भक्ति ही प्रमाण है।”\n\nयह कहकर माँ गौरी ने अपने वरद-हस्त को वीरवती के पति के शरीर पर रखा और मुस्कुराकर कहा —\n\n“ॐ गौर्यै नमः। सौभाग्यं चिरायुश्च सदा तेऽस्तु।”\n\n(ॐ गौरी को नमस्कार। तुम्हारा सौभाग्य और दीर्घायु सदा रहे।)\n\nउसी क्षण दिव्य प्रकाश और भी तीव्र हो गया। वीरवती के पति के शरीर में प्राण का संचार हुआ। उनकी छाती धीरे-धीरे उठने लगी, होंठ हिले और आँखें खुलीं। उन्होंने अपने चारों ओर देखा और वीरवती को अपने सम्मुख देखकर आश्चर्य से बोले —\n\n“प्रिये! क्या तुम रो रही हो? मैं तो सो गया था। सारे शरीर में विश्राम का अनुभव हो रहा है। क्या मुझे कुछ हुआ था?”\n\nवीरवती ने अपने पति को जीवित देखकर आँसुओं के साथ हँसते हुए कहा —\n\n“स्वामी! आपने जीवनदान पाया है। यह माँ गौरी का आशीर्वाद है। मैंने आपके लिए व्रत किया था, पर भाइयों की भूल से मेरा व्रत अधूरा रह गया। तब माँ गौरी ने स्वयं दर्शन देकर आपको जीवनदान दिया है।”\n\nमाँ गौरी ने उन दोनों को स्नेह से देखा और वीरवती से कहा —\n\n“पुत्रि! अब तुम विधिपूर्वक चन्द्रमा का दर्शन करो और व्रत का पारण करो। सायंकाल होने पर जब चन्द्रोदय होगा, तुम छलनी से चन्द्र-दर्शन करके पति के हाथ से जल ग्रहण करना। यही करवा चौथ का पूर्ण विधान है। तुम्हारा यह व्रत सदा तुम्हारे सुहाग की रक्षा करेगा।”\n\nवीरवती ने हाथ जोड़कर पूछा —\n\n“माता! मेरे भाइयों ने अज्ञानवश जो भूल की, उनका क्या होगा? वे मेरे प्राणों के समान हैं। उन्होंने मेरे लिए ही ऐसा किया था।”\n\nमाँ गौरी मुस्कुराईं —\n\n“पुत्रि! तुम्हारा हृदय करुणा से भरा है। तुम्हारे भाइयों ने जो किया, वह मोहवश किया। यदि वे पश्चाताप करके इस व्रत का महात्म्य सुनें और मेरी पूजा करें, तो उनका पाप भी भस्म हो जाएगा। परन्तु तुम उन्हें बताओ कि व्रत में किसी भी प्रकार का भ्रम न करें। व्रत का पालन सच्चे मन से और विधि के अनुसार ही करें।”\n\nयह कहकर माँ गौरी अन्तर्धान हो गईं। वीरवती ने हाथ जोड़कर उन्हें प्रणाम किया और अपने पति को सारी बात बताई। पति ने श्रद्धापूर्वक गौरी-शिव का पूजन किया और दोनों ने मिलकर माँ का आशीर्वाद लिया।\n\nजब भाइयों को यह समाचार मिला कि उनका बहनोई जीवित हो गया है और माँ गौरी ने स्वयं दर्शन दिए हैं, तो वे दौड़कर आए। उन्होंने बहन और बहनोई के चरण छुए और हाथ जोड़कर कहा —\n\n“बहन! हमने तुम्हारे व्रत में विघ्न डाला था, हमें क्षमा कर दो। हमें व्रत की विधि का ज्ञान नहीं था। अब हमें वह विधि बताओ, जिससे हम अपने जीवन में भी इस व्रत का पालन कर सकें।”\n\nवीरवती ने कहा —\n\n“भाइयों! व्रत का फल केवल व्रत से नहीं, श्रद्धा और सच्चे संकल्प से मिलता है। माँ गौरी की कृपा से मेरा सुहाग लौटा है। अब मैं तुम्हें यह व्रत की विधि बताती हूँ, जो माँ गौरी ने स्वयं मुझे बताई है।”\n\nउसी दिन सायंकाल, जब सूर्यदेव अस्त हो गए और आकाश में तारे चमकने लगे, वीरवती ने पूजा-स्थल सजाया। मिट्टी के करवे को जल से भरा, उस पर रोली का स्वस्तिक बनाया और उसमें फूल, अक्षत, और मिष्ठान रखे। उसने गौरी-शिव की प्रतिमा को स्नान कराया और धूप-दीप से पूजन किया।\n\nतभी आकाश में चन्द्रमा उदय हुए। उनकी शीतल किरणें चारों ओर फैल गईं। वीरवती ने छलनी हाथ में ली और उसके माध्यम से चन्द्रदेव का दर्शन किया। उसने प्रार्थना की —\n\n“ॐ सोमाय नमः। हे चन्द्रदेव! आप अमृतमय और शीतल हैं। आपके दर्शन से सुहाग की रक्षा होती है। मेरे पति की आयु, हमारे सुहाग और परिवार की शान्ति की रक्षा करें।”\n\nफिर उसने अपने पति के हाथ से जल ग्रहण किया और विधिपूर्वक पारण किया। उसी क्षण घर में आनन्द की वर्षा हो गई। सारे नगर में उत्सव मनाया गया। वीरवती और उसके पति ने माँ गौरी के चरणों में पुष्पांजलि अर्पित की और सुखपूर्वक जीवन व्यतीत करने लगे।\n\nयह देखकर भाइयों ने भी संकल्प लिया कि वे प्रत्येक वर्ष कार्तिक कृष्ण चतुर्थी को इस व्रत को श्रद्धापूर्वक करेंगे और किसी भी प्रकार का भ्रम नहीं करेंगे। उन्होंने वीरवती से व्रत की सम्पूर्ण विधि सीखी —\n\n1. प्रातः स्नान करके संकल्प लेना।\n2. निर्जला व्रत रखना।\n3. सायंकाल गौरी-शिव का पूजन करना।\n4. चन्द्रोदय होने पर छलनी से चन्द्र-दर्शन करना।\n5. पति के हाथ से जल ग्रहण करके पारण करना।\n6. व्रत की कथा श्रद्धापूर्वक सुनना।\n\nधीरे-धीरे यह व्रत सारे राज्य में प्रसिद्ध हो गया। सभी सुहागिन स्त्रियाँ करवा चौथ का व्रत श्रद्धा से करने लगीं और माँ गौरी की कृपा से सुखी जीवन व्यतीत करने लगीं।";

    $ch4Title = "व्रत का महात्म्य एवं फलश्रुति";
    $ch4Story = "कैलाश पर्वत पर भगवान शंकर अपनी प्रिय पार्वती के साथ बैठे थे। माँ पार्वती ने करुणा से भरकर पूछा —\n\n“स्वामी! आपने मुझे वीरवती की कथा सुनाई। अब कृपया यह बताइए कि इस करवा चौथ व्रत का महात्म्य क्या है? इस व्रत को करने से कौन-कौन से फल प्राप्त होते हैं? और इस व्रत के पालन में किन नियमों का पालन करना चाहिए?”\n\nभगवान शिव ने मुस्कुराकर कहा —\n\n“देवि! तुमने बहुत उत्तम प्रश्न पूछा है। सुनो, मैं तुम्हें इस व्रत का सम्पूर्ण महात्म्य बताता हूँ।”\n\nभगवान शिव बोले —\n\n“जो स्त्री कार्तिक कृष्ण चतुर्थी को करवा चौथ का व्रत रखती है, वह मानो मेरी अर्धांगिनी गौरी की ही पूजा करती है। इस व्रत में माँ गौरी, मैं (शिव) और चन्द्रमा — तीनों की उपासना की जाती है। यह व्रत सुहागिन स्त्रियों के लिए सौभाग्य, पति की दीर्घायु और अखण्ड सुहाग का परम साधन है।”\n\nमाँ पार्वती ने पूछा —\n\n“स्वामी! इस व्रत की विधि क्या है? कृपया विस्तार से बताइए।”\n\nभगवान शिव ने कहा —\n\n“देवि! सुनो, व्रत की विधि इस प्रकार है —\n\nसंकल्प: प्रातः स्नान करके स्वच्छ वस्त्र पहनें। मिट्टी के करवे को जल से भरकर, उस पर रोली से स्वस्तिक बनाएँ। हाथ में जल और अक्षत लेकर संकल्प करें कि ‘मैं अपने पति के दीर्घायुष्य और सौभाग्य के लिए यह निर्जला व्रत रखती हूँ।’\n\nनिर्जला व्रत: दिनभर अन्न-जल ग्रहण न करें। यदि शरीर अस्वस्थ हो तो शास्त्र और चिकित्सक के परामर्श से फलाहार कर सकती हैं।\n\nसायंकाल पूजन: सूर्यास्त से पहले गौरी-शिव की प्रतिमा या चित्र का विधिवत पूजन करें। धूप, दीप, पुष्प, अक्षत, मिष्ठान अर्पित करें। करवे को पुष्पों से सजाएँ।\n\nकथा श्रवण: करवा चौथ की कथा श्रद्धापूर्वक सुनें या पढ़ें।\n\nचन्द्र-दर्शन: रात्रि में चन्द्रोदय होने पर छलनी हाथ में लेकर चन्द्रमा का दर्शन करें। पहले चन्द्रमा को अर्घ्य दें, फिर छलनी से अपने पति का मुख देखें।\n\nपारण: पति के हाथ से जल ग्रहण करें और फिर प्रसाद ग्रहण करके व्रत पूर्ण करें।”\n\nमाँ पार्वती ने पूछा —\n\n“स्वामी! इस व्रत का फल क्या है? जो स्त्री यह व्रत करती है, उसे क्या-क्या लाभ मिलते हैं?”\n\nभगवान शिव ने कहा —\n\n“देवि! इस व्रत का फल अत्यन्त महान है। जो स्त्री श्रद्धा और भक्ति से यह व्रत करती है —\n\nउसके पति की आयु बढ़ती है।\nउसका सौभाग्य अखण्ड रहता है।\nपति-पत्नी में प्रेम और विश्वास बढ़ता है।\nसंतान सुख की प्राप्ति होती है।\nघर में सुख, शान्ति और समृद्धि आती है।\nअकाल मृत्यु का भय दूर होता है।\nजो स्त्री यह व्रत करती है, उसे सात जन्मों तक सौभाग्य की प्राप्ति होती है।\nजो स्त्री इस व्रत को नहीं कर सकती, वह कथा सुनकर और माँ गौरी का ध्यान करके भी पुण्य प्राप्त कर सकती है।”\n\nमाँ पार्वती ने कहा —\n\n“स्वामी! आपने वीरवती की कथा सुनाई, जिसमें उसके भाइयों ने मोहवश उसे चन्द्रमा का भ्रम देकर पारण करा दिया था। इससे क्या शिक्षा मिलती है?”\n\nभगवान शिव ने कहा —\n\n“देवि! इस कथा से यह शिक्षा मिलती है कि व्रत में किसी भी प्रकार का भ्रम, छल या अधूरा पालन नहीं करना चाहिए। व्रत का फल केवल विधिपूर्वक और सच्चे संकल्प से ही मिलता है। भाइयों ने स्नेहवश भूल की, परन्तु वीरवती ने अपने संकल्प को नहीं छोड़ा। उसकी दृढ़ भक्ति और माँ गौरी की कृपा से उसका सुहाग लौट आया। इसलिए प्रत्येक स्त्री को चाहिए कि वह व्रत को पूर्ण श्रद्धा से करे और किसी के बहकावे में न आए।”\n\nतत्पश्चात भगवान शिव ने कहा —\n\n“देवि! जो व्यक्ति इस करवा चौथ व्रत की कथा को श्रद्धापूर्वक सुनता या पढ़ता है, उसे इस व्रत का सम्पूर्ण फल प्राप्त होता है। जो स्त्री इस कथा को सुनकर व्रत करती है, उसका सुहाग अखण्ड रहता है और अन्त में वह अपने पति के साथ शिवलोक को प्राप्त होती है।”\n\nइस प्रकार भगवान शंकर ने माँ पार्वती को करवा चौथ व्रत का सम्पूर्ण महात्म्य बताया। माँ पार्वती ने हाथ जोड़कर कहा —\n\n“ॐ गौर्यै नमः। हे जगदम्बिके! आप सभी सुहागिन स्त्रियों को सौभाग्य प्रदान करें।”\n\nइति श्री करवा चौथ व्रत कथा सम्पूर्णम्।";

