        "status" => "success",
        "message" => "Karwa Chauth Vrat Katha successfully updated with all 4 comprehensive chapters in MySQL.",
        "upserted_ids" => $idsToUpsert,
        "total_chapters" => 4,
        "katha_text_length" => mb_strlen($kathaFullText, 'UTF-8'),
        "timestamp" => date('c')
    ];

    if ($isCli) {
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) . "\n";
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        echo json_encode($response, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE);
    }

} catch (Throwable $e) {
    $errResp = [
        "status" => "error",
        "message" => $e->getMessage(),
        "trace" => $e->getTraceAsString()
    ];
    if ($isCli) {
        fwrite(STDERR, json_encode($errResp, JSON_PRETTY_PRINT) . "\n");
        exit(1);
    } else {
        header("Content-Type: application/json; charset=UTF-8");
        http_response_code(500);
        echo json_encode($errResp, JSON_PRETTY_PRINT);
    }
}
